// Shared helpers for the Homelab cards (Business Text panels). Runs inside Grafana as the panel's
// "Before content rendering" code, with `context` in scope. Everything here is plain ES2018 so it can
// also be unit-tested in Node (tools/ui/test_ui.js).
//
// Data arrives in "All data" mode: an array of frames, each an array of records keyed by field name.
// Each query is tagged with a `q` label (label_replace in the PromQL) so we never depend on frame order.
const HOSTS = [["proxmox", "Proxmox"], ["pihole", "Pi-hole"], ["dockers", "Docker"], ["tailscale", "Tailscale"], ["plex", "Plex"], ["qbittorrent", "qBittorrent"]];   // [["proxmox", "Proxmox"], ...] display names, filled in by gen_home.py

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const slug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

function records(data) {
  const out = [];
  const walk = (d) => {
    if (Array.isArray(d)) d.forEach(walk);
    else if (d && typeof d === "object") out.push(d);
  };
  walk(data);
  return out;
}

function num(r) {
  if (!r) return NaN;
  if (typeof r.Value === "number") return r.Value;
  const k = Object.keys(r).find((x) => /^Value/.test(x));
  const v = k === undefined ? NaN : Number(r[k]);
  return Number.isFinite(v) ? v : NaN;
}

const only = (recs, q) => recs.filter((r) => r.q === q);
const first = (recs, q, fallback) => {
  const v = num(only(recs, q)[0]);
  return Number.isFinite(v) ? v : fallback;
};

const clamp = (v) => Math.max(0, Math.min(100, Math.round(v)));
const tone = (v) => (v >= 90 ? "crit" : v >= 75 ? "warn" : "");
const hostName = (raw) => {
  const hit = HOSTS.find((h) => h[0] === raw);
  return hit ? hit[1] : raw;
};

// "99.98%" but "100%" for a perfect score, and never more than two decimals
const pct = (v) => {
  if (!Number.isFinite(v)) return "n/a";
  const s = v.toFixed(2);
  return (s.endsWith(".00") ? s.slice(0, -3) : s.replace(/0$/, "")) + "%";
};

const ms = (v) => (!Number.isFinite(v) ? "n/a" : v >= 1000 ? (v / 1000).toFixed(1) + " s" : Math.round(v) + " ms");

const list = (items) =>
  items.length <= 1 ? items.join("") : items.slice(0, -1).join(", ") + " and " + items[items.length - 1];

// One line, no blank lines, no indentation: the plugin runs the output through a markdown pass, and a
// blank line or four leading spaces would turn part of it into a paragraph or a code block.
const wrap = (cls, inner) => '<div class="hlw"><div class="hl ' + cls + '">' + inner + "</div></div>";

const skeleton = (title) =>
  wrap("skel", '<div class="hd"><span class="ti">' + esc(title) + '</span><span class="su">Waiting for data</span></div>');

// Status header: one sentence that answers "is everything up?", then three numbers.
function renderHeader(data) {
  const R = records(data);
  const up = first(R, "up", 0), down = first(R, "down", 0), pend = first(R, "pend", 0);
  const total = up + down + pend;
  const uptime = first(R, "up30", NaN);

  const bad = only(R, "svc").filter((r) => num(r) !== 1 && Number.isFinite(num(r)));
  const downNames = bad.filter((r) => num(r) === 0).map((r) => String(r.monitor_name).trim());
  const waitNames = bad.filter((r) => num(r) !== 0).map((r) => String(r.monitor_name).trim());
  const hosts = only(R, "hup");
  const offline = hosts.filter((r) => num(r) === 0).map((r) => hostName(r.host));
  const hostsOn = hosts.length - offline.length;

  let state = "ok", head = "All systems operational";
  if (downNames.length || down > 0) { state = "crit"; head = "Service outage"; }
  else if (waitNames.length || pend > 0 || offline.length) { state = "warn"; head = "Degraded performance"; }

  const notes = [];
  if (downNames.length) notes.push(list(downNames) + " down");
  if (waitNames.length) notes.push(list(waitNames) + " pending");
  if (offline.length) notes.push(list(offline) + " offline");
  const sub = notes.length ? notes.join(" · ") : total + " services and " + hosts.length + " hosts are healthy";

  const stat = (key, value, of, cap) =>
    '<div class="stat"><div class="num"><span class="cnt k_' + key + '">' + value + "</span>" +
    (of === "" ? "" : '<span class="of"> ' + of + "</span>") + '</div><div class="cap">' + cap + "</div></div>";

  return wrap("head " + state,
    '<div class="lead"><span class="dot"></span><div class="msg"><div class="h">' + esc(head) +
    '</div><div class="s">' + esc(sub) + "</div></div></div>" +
    '<div class="stats">' +
    stat("svc", up, "of " + total, "Services up") +
    stat("hst", hostsOn, "of " + hosts.length, "Hosts online") +
    stat("up30", pct(uptime), "", "Uptime, 30 days") +
    "</div>");
}
context.handlebars.registerHelper("header", (data) => renderHeader(data));

