options.afterRender:
// Runs after the card's HTML is in the DOM. The plugin replaces the HTML whenever a value changes, which
// would make bars jump, so this keeps the previous value of every meter and number in window state and
// animates from it to the new one. First load grows from zero. Without this code the cards still show the
// right values (each bar has a static width class); this only adds motion.
const el = context.element;
const S = (window.__homelab = window.__homelab || {});
const calm = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const keyOf = (n) => { const m = /\bk_([\w-]+)/.exec(n.className); return m && m[1]; };
const frames = [];

el.querySelectorAll(".fil").forEach((n) => {
  const key = keyOf(n), m = /\bw(\d+)\b/.exec(n.className);
  if (!key || !m) return;
  const to = Number(m[1]), from = S["f_" + key] === undefined ? 0 : S["f_" + key];
  S["f_" + key] = to;
  if (calm) { n.style.width = to + "%"; return; }
  n.style.transition = "none";
  n.style.width = from + "%";
  void n.offsetWidth;
  n.style.transition = "width 900ms cubic-bezier(.22,.8,.24,1), background-color 400ms ease";
  n.style.width = to + "%";
});

el.querySelectorAll(".cnt").forEach((n) => {
  const key = keyOf(n), m = /^(-?\d+(?:\.\d+)?)(.*)$/.exec(n.textContent.trim());
  if (!key || !m || n.children.length) return;
  const to = parseFloat(m[1]), dec = (m[1].split(".")[1] || "").length, tail = m[2];
  const from = S["c_" + key];
  S["c_" + key] = to;
  if (calm || from === undefined || from === to) return;
  const t0 = performance.now();
  const step = (t) => {
    const p = Math.min(1, (t - t0) / 800), e = 1 - Math.pow(1 - p, 3);
    n.textContent = (from + (to - from) * e).toFixed(dec) + tail;
    if (p < 1) frames.push(requestAnimationFrame(step));
  };
  frames.push(requestAnimationFrame(step));
});

return () => frames.forEach((f) => cancelAnimationFrame(f));

options.helpers:
// Shared helpers for the Homelab cards (Business Text panels). Runs inside Grafana as the panel's
// "Before content rendering" code, with `context` in scope. Everything here is plain ES2018 so it can
// also be unit-tested in Node (tools/ui/test_ui.js).
//
// Data arrives in "All data" mode: an array of frames, each an array of records keyed by field name.
// Each query is tagged with a `q` label (label_replace in the PromQL) so we never depend on frame order.
const HOSTS = [["proxmox", "Proxmox"], ["pihole", "Pi-hole"], ["dockers", "Docker"], ["tailscale", "Tailscale"], ["plex", "Plex"], ["qbittorrent", "qBittorrent"]];   // [["proxmox", "Proxmox"], ...] display names, filled in by gen_home.py

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const slug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

function records(data) {
  const out = [];
  const walk = (d) => {
    if (Array.isArray(d)) d.forEach(walk);
    else if (d && typeof d === "object") out.push(d);
  };
  walk(data);
  return out;
}

function num(r) {
  if (!r) return NaN;
  if (typeof r.Value === "number") return r.Value;
  const k = Object.keys(r).find((x) => /^Value/.test(x));
  const v = k === undefined ? NaN : Number(r[k]);
  return Number.isFinite(v) ? v : NaN;
}

const only = (recs, q) => recs.filter((r) => r.q === q);
const first = (recs, q, fallback) => {
  const v = num(only(recs, q)[0]);
  return Number.isFinite(v) ? v : fallback;
};

const clamp = (v) => Math.max(0, Math.min(100, Math.round(v)));
const tone = (v) => (v >= 90 ? "crit" : v >= 75 ? "warn" : "");
const hostName = (raw) => {
  const hit = HOSTS.find((h) => h[0] === raw);
  return hit ? hit[1] : raw;
};

// "99.98%" but "100%" for a perfect score, and never more than two decimals
const pct = (v) => {
  if (!Number.isFinite(v)) return "n/a";
  const s = v.toFixed(2);
  return (s.endsWith(".00") ? s.slice(0, -3) : s.replace(/0$/, "")) + "%";
};

const ms = (v) => (!Number.isFinite(v) ? "n/a" : v >= 1000 ? (v / 1000).toFixed(1) + " s" : Math.round(v) + " ms");

const list = (items) =>
  items.length <= 1 ? items.join("") : items.slice(0, -1).join(", ") + " and " + items[items.length - 1];

// One line, no blank lines, no indentation: the plugin runs the output through a markdown pass, and a
// blank line or four leading spaces would turn part of it into a paragraph or a code block.
const wrap = (cls, inner) => '<div class="hlw"><div class="hl ' + cls + '">' + inner + "</div></div>";

const skeleton = (title) =>
  wrap("skel", '<div class="hd"><span class="ti">' + esc(title) + '</span><span class="su">Waiting for data</span></div>');

// Service list: status dot, name, response time, 30-day uptime. Problems sort to the top.
const STATUS = { 0: ["Down", "crit"], 2: ["Pending", "warn"], 3: ["Maintenance", "info"] };
function renderServices(data) {
  const R = records(data);
  const st = only(R, "svc");
  if (!st.length) return skeleton("Services");
  const name = (r) => String(r.monitor_name).trim();
  const find = (q, n) => num(only(R, q).find((r) => name(r) === n));

  const items = st.map((r) => ({ n: name(r), s: num(r), ms: find("resp", name(r)), up: find("svcup", name(r)) }))
    .sort((a, b) => (a.s === 1) - (b.s === 1) || a.n.localeCompare(b.n));
  const upCount = items.filter((i) => i.s === 1).length;

  const rows = items.map((i) => {
    const bad = STATUS[i.s];
    return '<div class="row' + (bad ? " " + bad[1] : "") + '"><span class="sd ' + (bad ? bad[1] : "ok") + '"></span><span class="nm">' + esc(i.n) +
      '</span><span class="rt">' + (bad ? '<span class="tag ' + bad[1] + '">' + bad[0] + "</span>" : ms(i.ms)) +
      '</span><span class="up">' + (Number.isFinite(i.up) ? pct(i.up) : "") + "</span></div>";
  }).join("");

  return wrap("svcs", '<div class="hd"><span class="ti">Services</span><span class="su">' + upCount + " of " + items.length + " up</span></div>" + rows);
}
context.handlebars.registerHelper("services", (data) => renderServices(data));

